contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 loanID) public payable {
        uint256 account = 0;

        c.approveTransfer(address(this), loanID); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            account = 0;
        } else {
            account = 1;
        }

        bool reverted = (account == 0);

        assert(reverted);
    }
}

