pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 loanID) internal {
        uint256 account = 0;
        try c.approveTransfer(address(this), loanID) {
            account = 1;
        } catch {
            account = 0;
        }
        bool reverted = (account == 0);
        assertTrue(reverted);
    }

    function testFuzz_run(uint256 loanID) public {
        _run(loanID);
    }

    receive() external payable {}
}
